INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32233$nota-0039$m32233$, $m32234$Training and Racing with a Power Meter.pdf$m32234$, $m32235$84$m32235$, $m32236$Instantaneous power output when riding on the road over variable terrain contributes to the highly variable nature of your wattage. One second it's 500 watts, the next second it's 0 watts, and the next it's 220 watts... it is actually just highly variable because of the nature of the terrain, the wind, the riders around and in front of you.$m32236$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32237$nota-0039$m32237$, $m32238$Training and Racing with a Power Meter.pdf$m32238$, $m32239$85$m32239$, $m32240$Rather than trying to hit a specific wattage target, you should attempt to stay within a particular range... For example, if your goal is to work the lactate system but not go too hard, you might focus on producing at least 300 watts, but not exceeding 320 watts, while holding a 90-rpm cadence.$m32240$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32241$nota-0039$m32241$, $m32242$nota-0006$m32242$, $m32243$complementa$m32243$, $m32244$mesmo tema de variabilidade de potência ao ar livre vs. ambiente controlado$m32244$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32245$nota-0040$m32245$, $m32246$Training and Racing with a Power Meter.pdf$m32246$, $m32247$87$m32247$, $m32248$we have presented a way to determine the optimum number of repeats in Table 5.1. These numbers are based on our review of more than 3,000 power-meter files and our experience of working with more than 1,000 athletes.$m32248$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32249$nota-0040$m32249$, $m32250$Training and Racing with a Power Meter.pdf$m32250$, $m32251$88$m32251$, $m32252$In the table, we have based the percentage drop-off on the third interval that you complete because typically, the effort that a rider can put forth in the first two intervals will be much higher than what that rider could actually repeat multiple times... we throw out those first two efforts for the purpose of determining when to stop a workout.$m32252$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32253$nota-0040$m32253$, $m32254$Training and Racing with a Power Meter.pdf$m32254$, $m32255$89$m32255$, $m32256$we must take the wattage in the third effort and subtract 5 percent from it (in this case, 340 × 0.05 = 17, and 340 – 17 = 323 watts) to determine when to stop the repeats. When the athlete cannot average at least this wattage (323) for his interval, he is going to stop.$m32256$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32257$nota-0040$m32257$, $m32258$nota-0022$m32258$, $m32259$pre-requisito$m32259$, $m32260$usa a definição de zonas de FTP para especificar a intensidade-alvo do intervalo (ex.: VO2max 106-120% FTP)$m32260$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32261$nota-0041$m32261$, $m32262$Training and Racing with a Power Meter.pdf$m32262$, $m32263$96$m32263$, $m32264$The lower part of Level 4 is what we call the Sub-Threshold level, or the Sweet Spot. This occurs at about 88–94 percent of your functional threshold power—on the cusp of both the Tempo level and the Lactate Threshold level.$m32264$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32265$nota-0041$m32265$, $m32266$Training and Racing with a Power Meter.pdf$m32266$, $m32267$96$m32267$, $m32268$We encourage the athletes we work with to train heavily in this area at the beginning of the racing season, before moving into training right at their FTP (91–105 percent). We then revisit this intensity level around the middle of June in the lead-up to a second peak in the fall... we incorporate this Sweet Spot training at least once or twice every 14 days.$m32268$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32269$nota-0041$m32269$, $m32270$nota-0028$m32270$, $m32271$complementa$m32271$, $m32272$o Sweet Spot é o iLevel 4a (88-95% do FTP) descrito na Tabela 3.5 de iLevels — pequena divergência de 1 ponto percentual no teto (94 vs 95) entre as duas passagens do mesmo livro, registrada em _revisao/conflitos/$m32272$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32273$nota-0042$m32273$, $m32274$Training and Racing with a Power Meter.pdf$m32274$, $m32275$89$m32275$, $m32276$For the VO2max system to adapt to a training stimulus, a minimal effort of 3 minutes is necessary, with the maximum duration being about 8 minutes. After 8 minutes, it's very difficult, if not impossible, for most people to maintain 106–120 percent of FTP.$m32276$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32277$nota-0042$m32277$, $m32278$nota-0022$m32278$, $m32279$complementa$m32279$, $m32280$detalha a faixa de duração do Nível 5 (VO2máx) da Tabela 3.1$m32280$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32281$nota-0043$m32281$, $m32282$Training and Racing with a Power Meter.pdf$m32282$, $m32283$106$m32283$, $m32284$Anaerobic Capacity (AC) efforts typically entail intervals of 2 minutes or less... The intensity of these efforts is far beyond what can be maintained aerobically. It is a supra-maximal intensity—that is, it requires more than 100 percent of your VO2max.$m32284$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32285$nota-0043$m32285$, $m32286$nota-0022$m32286$, $m32287$complementa$m32287$, $m32288$detalha fisiologicamente por que o Nível 6 (Anaerobic Capacity) da Tabela 3.1 exige intensidade supra-máxima$m32288$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32289$nota-0044$m32289$, $m32290$Training and Racing with a Power Meter.pdf$m32290$, $m32291$108$m32291$, $m32292$It's called the 'micro-burst workout.'... Since the efforts are 15 seconds each, using an indoor trainer makes them highly controllable.$m32292$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32293$nota-0044$m32293$, $m32294$Training and Racing with a Power Meter.pdf$m32294$, $m32295$109$m32295$, $m32296$do two sets of micro-bursts lasting 10 minutes each. A micro-burst effort is 15 seconds on and 15 seconds off, repeated continually for the 10 minutes. For the on segment, go to 150 percent of FTP... and draw back to 50 percent of FTP... for the 15-second off segment.$m32296$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32297$nota-0044$m32297$, $m32298$nota-0022$m32298$, $m32299$complementa$m32299$, $m32300$trabalha tanto o Nível 7 (neuromuscular) quanto o Nível 4 (limiar), sendo classificado pelo livro em ambos os níveis simultaneamente$m32300$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32301$nota-0046$m32301$, $m32302$Training and Racing with a Power Meter.pdf$m32302$, $m32303$104$m32303$, $m32304$Hunter's examination of power-meter files has proven that the race-winning move always contains an initial attack to create separation from the field—that is, a breakaway—then a continued high effort to establish the separation, followed by a relative settling in at threshold power and a finish with a short burst of speed.$m32304$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m32305$nota-0046$m32305$, $m32306$Training and Racing with a Power Meter.pdf$m32306$, $m32307$105$m32307$, $m32308$Each effort begins with a 30-second sprint (15 seconds out of the saddle), averaging approximately 200 percent of threshold power, and peaking at around 300 percent... Then ride for 3 minutes at 100–110 percent of FTP... and finish with a 10-second burst, trying to reach 200–250 percent of FTP.$m32308$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m32309$nota-0046$m32309$, $m32310$nota-0042$m32310$, $m32311$complementa$m32311$, $m32312$a fase de sustentação da jogada vencedora ocorre na janela VO2max/limiar detalhada na nota-0042$m32312$)
